import ast

# Parse the code for syntax validation only
user_code = code
try:
    tree = ast.parse(user_code)
except SyntaxError as e:
    raise AssertionError(f'Syntax error: {e}')

# Check for sqlite3 import
found_sqlite = False
for node in ast.walk(tree):
    if isinstance(node, ast.Import) and any(name.name == 'sqlite3' for name in node.names):
        found_sqlite = True
    if isinstance(node, ast.ImportFrom) and node.module == 'sqlite3':
        found_sqlite = True

if not found_sqlite:
    raise AssertionError('Task 1: Missing import sqlite3')

# Check for with statement (context manager)
found_with = False
for node in ast.walk(tree):
    if isinstance(node, ast.With):
        found_with = True

if not found_with:
    raise AssertionError('Task 2: Missing with statement for database connection')

# Check for sqlite3.connect() call
found_connect = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
        if isinstance(node.func.value, ast.Name) and node.func.value.id == 'sqlite3' and node.func.attr == 'connect':
            found_connect = True

if not found_connect:
    raise AssertionError('Task 2: Missing sqlite3.connect() call')

# Check for cursor creation (.cursor() call)
found_cursor = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'cursor':
        found_cursor = True

if not found_cursor:
    raise AssertionError('Task 3: Missing .cursor() method call')

# Check for print statement with expected message
found_print = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == 'print':
        found_print = True
        # Check for the message in args (simplified)
        if node.args:
            msg = ast.unparse(node.args[0])
            if 'Successfully connected' in msg or 'success' in msg.lower():
                pass

if not found_print:
    raise AssertionError('Task 4: Missing print statement')

# Check for conn.close() call
found_close = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'close':
        found_close = True

if not found_close:
    raise AssertionError('Task 5: Missing conn.close() call')

print('TEST_PASSED')
